<template>
  <div class="optimization">
    <OptimizationHeader
      title="Объявления"
      status="Сейчас на странице"
      :count="totalPublications"
    />
    <CustomMainHeader
      :showCreateButton="false"
      :sortOptions="[
        { label: 'Все', value: 'desc' },
        { label: 'Опубликованные', value: 'asc' },
        { label: 'На модерации', value: 'asc' },
        { label: 'Снятые с публикации', value: 'asc' },
        { label: 'Архивированные', value: 'asc' },
      ]"
    />
    <div class="optimization-table__box">
      <CustomTable
        :ItemRows="itemRow"
        :headerRows="headerRows"
        :lineClamp="5"
        height="120px"
        @slot-clicked="handleButtonClick"
        @item-clicked="handleArrowOptionClick"
        :tablePagination="false"
        :totalPages="totalPages"
      >
        <template #slot-start="{ item }">
          <CustomStatus :id="item.customOptionStart.id" status="Опубликовано" />
        </template>
        <!-- Слот в конце строки -->
        <template #slot-end="{ item, emitEvent }">
          <CustomTableOption
            v-model="selectRole"
            :options="options"
            @update:model-value="handleOptionChange(item, emitEvent)"
          />
        </template>
      </CustomTable>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import CustomMainHeader from '@/components/UI/CustomMainHeader.vue';
import CustomTable from '@/components/UI/CustomTable.vue';
import { getCars } from '@/services/apiClient';
import CustomTableOption from '@/components/UI/CustomTableOption.vue';
import OptimizationHeader from '@/components/SEO/OptimizationHeader.vue';
import CustomStatus from '@/components/PUBLICATION/CustomStatus.vue';
import { useRouter } from 'vue-router';

const router = useRouter();

const options = [
  {
    name: 'Продвигать объявление',
    code: 'promoteAd',
    error: false,
    success: false,
    svg: 'promote-svg',
    ValidateType: 'select',
  },
  {
    name: 'Снять с публикации',
    code: 'unpublishAd',
    error: false,
    success: false,
    svg: 'unpublish-svg',
    ValidateType: 'select',
  },
  {
    name: 'Редактировать',
    code: 'editAd',
    error: false,
    success: false,
    svg: 'edit-svg',
    ValidateType: 'select',
  },
  {
    name: 'Переместить в архив',
    code: 'archiveAd',
    error: false,
    success: false,
    svg: 'archive-svg',
    ValidateType: 'select',
  },
  {
    name: 'Удалить',
    code: 'deleteAd',
    error: false,
    success: false,
    svg: 'delet-svg',
    ValidateType: 'select',
  },
];

const selectRole = ref({
  name: '',
  code: '',
  ValidateType: 'select',
  error: false,
  success: false,
});

const itemRow = ref([]);
const currentStep = ref(1);
const totalPublications = ref(1);
const count = 50;
const orderBy = 'desc';

const headerRows = [
  { name: 'ID', width: '120px', helper: false },
  { name: 'Заголовок', width: '250px', helper: false },
  { name: 'Цена', width: '120px', helper: false },
  { name: 'Владелец', width: '200px', helper: false },
  { name: 'Локация', width: '150px', helper: false },
  { name: 'Дата', width: '120px', helper: false },
  { name: '', width: '50px', helper: false },
];

const handleButtonClick = (item) => {
  router.push(`/publication/${item.id.value}`);
};

const handleOptionChange = (item, emitEvent) => {
  console.log('Изменение в опции:', selectRole, emitEvent);
};

const handleArrowOptionClick = (item) => {
  const id =
    item?.id?.value || item?.customOptionEnd?.id || item?.customOptionStart?.id;
  if (!id) return console.warn('Не удалось определить ID из item', item);
  router.push(`/publication/${id}`);
};

const fetchPublications = async () => {
  try {
    const response = await getCars({
      count,
      step: currentStep.value,
      order_by: orderBy,
    });

    const publications = response.data || [];

    itemRow.value = publications.map((publication) => ({
      customOptionStart: {
        slot: 'start',
        contenteditable: false,
        id: publication.id,
      },
      title: {
        value:
          `${
            publication.auto_technical_specifications?.[0]?.brand?.title || '—'
          } ` +
          `${
            publication.auto_technical_specifications?.[0]?.model?.title || ''
          } ` +
          `${
            publication.auto_technical_specifications?.[0]?.year_release
              ?.title || ''
          }` +
          '\n' +
          (publication.auto_history_conditions?.[0]?.mileage
            ? ` Пробег: ${publication.auto_history_conditions[0].mileage} км`
            : ''),
        type: 'text',
        contenteditable: false,
      },
      price: {
        value: publication.ads_parameter?.amount
          ? `${publication.ads_parameter.amount} ₽`
          : '—',
        type: 'text',
        contenteditable: false,
      },
      owner: {
        value:
          (publication.ads_parameter?.username || '—') +
          '\n' +
          (publication.ads_parameter?.phone || '—'),
        type: 'text',
        contenteditable: false,
      },
      location: {
        value: publication.ads_parameter?.city.title || '—',
        type: 'text',
        contenteditable: false,
      },
      date: {
        value: publication.created_at
          ? new Date(publication.created_at).toLocaleDateString('ru-RU') +
            '\n' +
            new Date(publication.created_at).toLocaleTimeString('ru-RU', {
              hour: '2-digit',
              minute: '2-digit',
            })
          : '—',
        type: 'text',
        contenteditable: false,
      },
      customOptionEnd: {
        slot: 'end',
        contenteditable: false,
        id: publication.id,
      },
    }));

    totalPublications.value = response.total_count;
  } catch (error) {
    console.error('Ошибка при загрузке объявлений', error);
  }
};

onMounted(async () => {
  await fetchPublications();
});
</script>

